# PostgreSQL is used when DATABASE_URL is configured; SQLite remains a local fallback.
DATABASE_URL = os.environ.get('DATABASE_URL', '').strip()

class Record(dict):
 def __getitem__(self, key):
  if isinstance(key, int): return list(self.values())[key]
  return super().__getitem__(key)
 def __getattr__(self, key):
  try: return self[key]
  except KeyError: raise AttributeError(key) from None

class PgResult:
 def __init__(self, cursor, lastrowid=None):
  self.cursor=cursor
  self.lastrowid=lastrowid
 def fetchone(self):
  row=self.cursor.fetchone()
  return Record(row) if row is not None else None
 def fetchall(self): return [Record(r) for r in self.cursor.fetchall()]
 def __iter__(self):
  for row in self.cursor: yield Record(row)

class PgConnection:
 def __init__(self): self.raw=pg_connect(DATABASE_URL, row_factory=dict_row)
 def __enter__(self): return self
 def __exit__(self, exc_type, exc, tb):
  try:
   if exc_type: self.raw.rollback()
   else: self.raw.commit()
  finally: self.raw.close()
 def execute(self, sql, args=()):
  sql=sql.replace('?', '%s')
  is_insert=sql.lstrip().upper().startswith('INSERT INTO')
  if is_insert and 'RETURNING' not in sql.upper(): sql += ' RETURNING id'
  self.raw.execute('SAVEPOINT sofia_stmt')
  try:
   cursor=self.raw.execute(sql, tuple(args))
   self.raw.execute('RELEASE SAVEPOINT sofia_stmt')
  except Exception:
   self.raw.execute('ROLLBACK TO SAVEPOINT sofia_stmt')
   self.raw.execute('RELEASE SAVEPOINT sofia_stmt')
   raise
  if is_insert:
   row=cursor.fetchone()
   return PgResult(cursor, row['id'] if row else None)
  return PgResult(cursor)

def conn():
 if DATABASE_URL: return PgConnection()
 c=sqlite3.connect(DB)
 c.row_factory=sqlite3.Row
 c.execute('PRAGMA foreign_keys=ON')
 return c

